/** Failure raised by every entry point in this module. */
export class SemverError extends Error {
  /** @param {string} message reason */
  constructor(message) {
    super(message);
    this.name = 'SemverError';
  }
}

const NUMERIC = '0|[1-9]\\d*';
const IDENT = '[0-9A-Za-z-]+';
const FULL = new RegExp(
  `^(${NUMERIC})\\.(${NUMERIC})\\.(${NUMERIC})` +
    `(?:-(${IDENT}(?:\\.${IDENT})*))?` +
    `(?:\\+(${IDENT}(?:\\.${IDENT})*))?$`,
);

const ALL_DIGITS = /^\d+$/;
const LEADING_ZERO = /^0\d+$/;

/**
 * Convert a raw prerelease identifier into its parsed form (a number for an
 * all-digit identifier with no leading zero, otherwise the string itself).
 *
 * @param {string} raw a single dot-separated identifier
 * @returns {string | number} the parsed identifier
 */
function parsePrereleaseIdentifier(raw) {
  if (ALL_DIGITS.test(raw)) {
    if (LEADING_ZERO.test(raw)) throw new SemverError(`invalid version: ${raw}`);
    return Number(raw);
  }
  return raw;
}

/**
 * Parse a semantic version.
 *
 * @param {string} version version text, optionally prefixed with `v` and surrounded by whitespace
 * @returns {{ major: number, minor: number, patch: number, prerelease: (string | number)[], build: string[], version: string }}
 *   the parsed version, with `version` holding the text without the `v` prefix
 */
export function parse(version) {
  if (typeof version !== 'string') throw new SemverError('version must be a string');
  const trimmed = version.trim();
  const stripped = trimmed.startsWith('v') || trimmed.startsWith('V') ? trimmed.slice(1) : trimmed;
  const matched = FULL.exec(stripped);
  if (matched === null) throw new SemverError(`invalid version: ${trimmed}`);
  const [, major, minor, patch, prereleaseText, buildText] = matched;
  const prerelease = prereleaseText === undefined
    ? []
    : prereleaseText.split('.').map((identifier) => {
      try {
        return parsePrereleaseIdentifier(identifier);
      } catch {
        throw new SemverError(`invalid version: ${trimmed}`);
      }
    });
  const build = buildText === undefined ? [] : buildText.split('.');
  return {
    major: Number(major),
    minor: Number(minor),
    patch: Number(patch),
    prerelease,
    build,
    version: stripped,
  };
}

/**
 * Coerce a version, given as text or already parsed, into its parsed form.
 *
 * @param {string | object} version version text or a parsed version
 * @returns {object} the parsed version
 */
function asParsed(version) {
  return typeof version === 'string' ? parse(version) : version;
}

/**
 * Compare two prerelease identifiers by the semver precedence rules.
 *
 * @param {string | number} a left identifier
 * @param {string | number} b right identifier
 * @returns {-1 | 0 | 1} the sign of `a - b`
 */
function compareIdentifier(a, b) {
  const aIsNumber = typeof a === 'number';
  const bIsNumber = typeof b === 'number';
  if (aIsNumber && bIsNumber) return a === b ? 0 : a < b ? -1 : 1;
  if (aIsNumber) return -1;
  if (bIsNumber) return 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

/**
 * Compare two versions by precedence, ignoring build metadata.
 *
 * @param {string | object} a left version, parsed or as text
 * @param {string | object} b right version, parsed or as text
 * @returns {-1 | 0 | 1} the sign of `a - b`
 */
export function compare(a, b) {
  const left = asParsed(a);
  const right = asParsed(b);

  if (left.major !== right.major) return left.major < right.major ? -1 : 1;
  if (left.minor !== right.minor) return left.minor < right.minor ? -1 : 1;
  if (left.patch !== right.patch) return left.patch < right.patch ? -1 : 1;

  const leftHasPrerelease = left.prerelease.length > 0;
  const rightHasPrerelease = right.prerelease.length > 0;
  if (leftHasPrerelease !== rightHasPrerelease) return leftHasPrerelease ? -1 : 1;
  if (!leftHasPrerelease) return 0;

  const length = Math.max(left.prerelease.length, right.prerelease.length);
  for (let index = 0; index < length; index += 1) {
    if (index >= left.prerelease.length) return -1;
    if (index >= right.prerelease.length) return 1;
    const result = compareIdentifier(left.prerelease[index], right.prerelease[index]);
    if (result !== 0) return result;
  }
  return 0;
}
