const IDENT = '[0-9A-Za-z-]+';
const PARTIAL = new RegExp(
  `^(${NUMERIC_OR_WILD})(?:\\.(${NUMERIC_OR_WILD}))?(?:\\.(${NUMERIC_OR_WILD}))?` +
    `(?:-(${IDENT}(?:\\.${IDENT})*))?$`,
);
const CLEAN_NUMBER = /^(0|[1-9]\d*)$/;
const OPERATOR = /^(<=|>=|\^|~|<|>|=)?([\s\S]*)$/;

/**
 * @param {string} raw major/minor/patch text
 * @returns {boolean} whether it stands for "any value"
 */
function isWildcard(raw) {
  return raw === 'x' || raw === 'X' || raw === '*';
}

/**
 * Parse a comparator's own version text, which may omit trailing parts or use
 * a wildcard for them, into a description of how many concrete parts it has.
 *
 * @param {string} rawText version text, possibly with a leading `v`
 * @returns {{ level: number, major: number, minor: number, patch: number, prerelease: (string|number)[] }}
 *   `level` is how many of major/minor/patch were given as concrete numbers (0 for a bare wildcard)
 */
function parsePartial(rawText) {
  const stripped = rawText.startsWith('v') || rawText.startsWith('V') ? rawText.slice(1) : rawText;
  const matched = PARTIAL.exec(stripped);
  if (matched === null) throw new SemverError(`invalid range: ${rawText}`);
  const [, majorRaw, minorRaw, patchRaw, prereleaseRaw] = matched;

  const readNumber = (raw) => {
    if (!CLEAN_NUMBER.test(raw)) throw new SemverError(`invalid range: ${rawText}`);
    return Number(raw);
  };

