    if (minorRaw !== undefined || patchRaw !== undefined || prereleaseRaw !== undefined) {
      throw new SemverError(`invalid range: ${rawText}`);
    }
    return { level: 0, major: 0, minor: 0, patch: 0, prerelease: [] };
  }

  const major = readNumber(majorRaw);

  if (minorRaw === undefined) {
    if (prereleaseRaw !== undefined) throw new SemverError(`invalid range: ${rawText}`);
    return { level: 1, major, minor: 0, patch: 0, prerelease: [] };
  }

  if (isWildcard(minorRaw)) {
    if (patchRaw !== undefined || prereleaseRaw !== undefined) {
      throw new SemverError(`invalid range: ${rawText}`);
    }
    return { level: 1, major, minor: 0, patch: 0, prerelease: [] };
