  if (patchRaw === undefined) {
    if (prereleaseRaw !== undefined) throw new SemverError(`invalid range: ${rawText}`);
    return { level: 2, major, minor, patch: 0, prerelease: [] };
  }

  if (isWildcard(patchRaw)) {
    if (prereleaseRaw !== undefined) throw new SemverError(`invalid range: ${rawText}`);
    return { level: 2, major, minor, patch: 0, prerelease: [] };
  }

  const patch = readNumber(patchRaw);
  let prerelease = [];
  if (prereleaseRaw !== undefined) {
    try {
      prerelease = parsePrereleaseIdentifiers(prereleaseRaw);
    } catch {
      throw new SemverError(`invalid range: ${rawText}`);
    }
  }
  return { level: 3, major, minor, patch, prerelease };
