 * Format the inclusive lower bound of a partial: given parts kept, missing
 * parts filled with zero, prerelease kept only when the version is full.
 *
 * @param {object} partial a parsed partial version
 * @returns {string} the formatted version text
 */
function formatLow(partial) {
  let text = `${partial.major}.${partial.minor}.${partial.patch}`;
  if (partial.level === 3 && partial.prerelease.length > 0) {
    text += `-${partial.prerelease.join('.')}`;
  }
  return text;
