/**
 * Format a full version's text, including its prerelease when present.
 *
 * @param {object} partial a parsed full (level 3) version
 * @returns {string} the formatted version text
 */
function formatFull(partial) {
  let text = `${partial.major}.${partial.minor}.${partial.patch}`;
  if (partial.prerelease.length > 0) text += `-${partial.prerelease.join('.')}`;
  return text;
}

