 * Format the version obtained by incrementing one part and zeroing the rest,
 * dropping any prerelease.
 *
 * @param {object} partial a parsed partial version
 * @param {number} bumpIndex which part (0 = major, 1 = minor, 2 = patch) to increment
 * @returns {string} the formatted version text
 */
function formatBump(partial, bumpIndex) {
  const values = [partial.major, partial.minor, partial.patch];
  values[bumpIndex] += 1;
  for (let index = bumpIndex + 1; index < 3; index += 1) values[index] = 0;
  return values.join('.');
}

/**
 * Find the caret operator's bump index: the leftmost non-zero part among the
 * parts actually given, or the last given part when they are all zero.
 *
 * @param {object} partial a parsed partial version, with `level` >= 1
 * @returns {number} the index to increment
 */
function caretBumpIndex(partial) {
  const values = [partial.major, partial.minor, partial.patch];
  for (let index = 0; index < partial.level; index += 1) {
    if (values[index] !== 0) return index;
  }
  return partial.level - 1;
}

