 * Expand one operator and its comparator version into concrete comparator
 * strings.
 *
 * @param {string} operator one of '', '=', '^', '~', '<', '<=', '>', '>='
 * @param {object} partial the parsed comparator version
 * @param {string} rawText the original version text, for error messages
 * @returns {string[]} the resulting comparator strings
 */
function comparatorsForOperator(operator, partial, rawText) {
  if (operator !== '' && operator !== '=' && partial.level === 0) {
    throw new SemverError(`invalid range: ${rawText}`);
  }

  if (operator === '' || operator === '=') {
    if (partial.level === 0) return ['>=0.0.0'];
    if (partial.level === 3) return [`=${formatFull(partial)}`];
    return [`>=${formatLow(partial)}`, `<${formatBump(partial, partial.level - 1)}`];
  }

  if (operator === '^') {
    const index = caretBumpIndex(partial);
    return [`>=${formatLow(partial)}`, `<${formatBump(partial, index)}`];
  }

  if (operator === '~') {
    const index = partial.level >= 2 ? 1 : 0;
    return [`>=${formatLow(partial)}`, `<${formatBump(partial, index)}`];
  }

  if (operator === '>=') return [`>=${formatLow(partial)}`];
  if (operator === '<') return [`<${formatLow(partial)}`];

  if (operator === '>') {
    if (partial.level === 3) return [`>${formatFull(partial)}`];
    return [`>=${formatBump(partial, partial.level - 1)}`];
  }

  if (operator === '<=') {
    if (partial.level === 3) return [`<=${formatFull(partial)}`];
    return [`<${formatBump(partial, partial.level - 1)}`];
  }

  throw new SemverError(`invalid range: ${rawText}`);
}

/**
 * Expand an `a - b` hyphen range into its comparator strings.
 *
 * @param {string} leftText left operand text
 * @param {string} rightText right operand text
 * @returns {string[]} the resulting comparator strings
 */
function hyphenComparators(leftText, rightText) {
  const left = parsePartial(leftText);
  const right = parsePartial(rightText);
  const comparators = [];
  if (left.level !== 0) comparators.push(`>=${formatLow(left)}`);
  if (right.level === 3) {
    comparators.push(`<=${formatFull(right)}`);
  } else if (right.level !== 0) {
    comparators.push(`<${formatBump(right, right.level - 1)}`);
  }
  if (comparators.length === 0) return ['>=0.0.0'];
  return comparators;
}

/**
 * Parse one `||`-separated alternative into its comparator strings.
 *
 * @param {string} altRaw the alternative text
 * @returns {string[]} the resulting comparator strings
 */
function parseAlternative(altRaw) {
  const alt = altRaw.trim();
  if (alt === '') return ['>=0.0.0'];

  const tokens = alt.split(/\s+/).filter((token) => token.length > 0);
  const hyphenIndex = tokens.indexOf('-');
  if (hyphenIndex !== -1) {
    if (tokens.length !== 3 || hyphenIndex !== 1) throw new SemverError(`invalid range: ${altRaw}`);
    return hyphenComparators(tokens[0], tokens[2]);
  }

  const comparators = [];
  let index = 0;
  while (index < tokens.length) {
    const token = tokens[index];
    const matched = OPERATOR.exec(token);
    const operator = matched[1] || '';
    let rest = matched[2];
    index += 1;
    if (rest === '') {
      if (index >= tokens.length) throw new SemverError(`invalid range: ${altRaw}`);
      rest = tokens[index];
      index += 1;
    }
    const partial = parsePartial(rest);
    comparators.push(...comparatorsForOperator(operator, partial, rest));
  }
  return comparators;
}

/**
 * Expand a range into readable comparator sets.
 *
 * @param {string} range range text
 * @returns {string[][]} one array of comparator strings per alternative
 */
export function parseRange(range) {
  if (typeof range !== 'string') throw new SemverError('range must be a string');
  return range.split('||').map((alt) => parseAlternative(alt));
}

const COMPARATOR = /^(<=|>=|=|<|>)(.*)$/;

/**
 * Parse a single comparator string, as produced by {@link parseRange}, into
 * its operator and version.
 *
 * @param {string} text a comparator string such as `>=1.2.3`
 * @returns {{ operator: string, version: object }} the parsed comparator
 */
function parseComparator(text) {
  const matched = COMPARATOR.exec(text);
  return { operator: matched[1], version: parse(matched[2]) };
}

/**
 * Test one already-parsed version against one already-parsed comparator.
 *
 * @param {object} version the parsed candidate version
 * @param {{ operator: string, version: object }} comparator the parsed comparator
 * @returns {boolean} whether the comparator holds
 */
function comparatorHolds(version, comparator) {
  const sign = compare(version, comparator.version);
  switch (comparator.operator) {
    case '=':
      return sign === 0;
    case '>':
      return sign > 0;
    case '>=':
      return sign >= 0;
    case '<':
      return sign < 0;
    case '<=':
      return sign <= 0;
    default:
      return false;
  }
}

/**
 * Test whether a parsed version satisfies one alternative's comparator set,
 * applying the prerelease-visibility rule.
 *
 * @param {object} version the parsed candidate version
 * @param {string[]} comparatorStrings the alternative's comparator strings
 * @param {boolean} includePrerelease whether to skip the prerelease-visibility rule
 * @returns {boolean} whether the alternative admits the version
 */
function alternativeMatches(version, comparatorStrings, includePrerelease) {
  const comparators = comparatorStrings.map(parseComparator);
  for (const comparator of comparators) {
    if (!comparatorHolds(version, comparator)) return false;
  }
  if (version.prerelease.length > 0 && !includePrerelease) {
